-- Spain 1936: unique units and buildings of the six sides, cloned from the stock rows at load time (generated by text/build_text.py).
-- The donor civilizations' own uniques are unhooked; stock 3D models, icons, techs and upgrade paths are kept.

-- T-26 (REP): UNIT_WWI_TANK
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_WWI_TANK';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_ESP1936_T26', Description = 'TXT_KEY_UNIT_ESP1936_T26', Civilopedia = 'TXT_KEY_CIV5_ESP1936_T26_TEXT', Strategy = 'TXT_KEY_UNIT_ESP1936_T26_STRATEGY', Help = 'TXT_KEY_UNIT_ESP1936_T26_HELP', Combat = 65;

